void Solver::bump_var(int var, double coeff) {
    if (coeff == 0.0) return;                     // nothing to do

    // increase activity of the variable
    double delta = var_inc * coeff;
    activity[var] += delta;

    // global lazy rescaling: trigger only when the increment factor or a single activity
    // becomes excessively large. This happens far less frequently than the original
    // per‑variable check and avoids repeated full‑array rescales.
    const double LIMIT = 1e100;
    if (var_inc > LIMIT || activity[var] > LIMIT) {
        const double SCALE = 1e-100;
        // scale down all activities in a tight loop
        for (int i = 1; i <= vars; ++i) activity[i] *= SCALE;
        var_inc *= SCALE;
    }

    // keep the VSIDS heap up‑to‑date
    if (vsids.inHeap(var)) vsids.update(var);
}
